class Solution {
public:
    long long minimumMoney(vector<vector<int>>& transactions) {
        long long total_loss = 0;
        long long max_cashback_losing = 0;
        long long max_cost_winning = 0;

        for (const auto& t : transactions) {
            long long cost = t[0];
            long long cashback = t[1];
            if (cashback < cost) {
                total_loss += cost - cashback;
                max_cashback_losing = max(max_cashback_losing, cashback);
            } else {
                max_cost_winning = max(max_cost_winning, cost);
            }
        }

        return total_loss + max(max_cashback_losing, max_cost_winning);
    }
};
